-- =============================================================================
-- 17-Multi-Instance-Subtask-Demo (Function Unit fu-20260422-23tfag)
-- Developer-workstation catalog only (dw_* + lookup-related rt_*).
-- Does NOT seed admin users, rt_table_access, or dev-specific audit user IDs.
-- Exported from dev DB on 2026-07-19 (full FU re-export after designer rebuild; all dw_* child ids refreshed),
-- then reconciled with real dev-DB drift observed 2026-08-20 (dw_versions 1.0.125 -> 1.0.143): adds the
-- "Meeting Remark" ACTION table (dw_table_definitions 50334) + FORM_POPUP "Add Remark" action (50384)
-- reachable from the assignment user task; adds relation table `meeting_room` (rt_table_definitions id 2,
-- current_version 2) used for lookup columns on the remark form; adopts the MI Assignment container in
-- several TASK/REQUEST form configs; adds `recordNote` nodes on two forms; renumbers several
-- form-table-bindings and sub/main table view configs to match live DB (stale 50295/50297/50298/50221/50382
-- rows removed); resyncs main/sub table view-config filters and columns; renames the "Withdraw" action
-- (50379) with its full FORM_POPUP config; adds dw_foreign_keys rows (previously unseeded); and fixes the
-- `test` relation table's (id 1) upsert to land on current_version=6 (was pinned back to 5) with the
-- matching rt_table_versions v6 snapshot row added. rt_ shared "test" table section now kept at v6.
-- Per-table main views (one default view per MAIN/SUB table); relation-table
-- lookup/relationViews now travel inside form config_json (no rt_view_*/rt_lookup_* rows).
-- =============================================================================
BEGIN;

DO $cleanup$
DECLARE v_fu_id bigint;
BEGIN
  SELECT id INTO v_fu_id FROM dw_function_units
  WHERE code = 'fu-20260422-23tfag' OR name = 'Multi-Instance Subtask Demo'
  ORDER BY id LIMIT 1;

  IF v_fu_id IS NULL THEN
    RETURN;
  END IF;

  DELETE FROM dw_main_table_view_fields
    WHERE view_config_id IN (
      SELECT id FROM dw_main_table_view_configs WHERE function_unit_id = v_fu_id
    );
  DELETE FROM dw_main_table_view_configs WHERE function_unit_id = v_fu_id;

  DELETE FROM dw_sub_table_view_fields
    WHERE view_config_id IN (
      SELECT c.id FROM dw_sub_table_view_configs c
      WHERE c.binding_id IN (
        SELECT id FROM dw_form_table_bindings
        WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id)
      )
    );
  DELETE FROM dw_sub_table_view_configs
    WHERE binding_id IN (
      SELECT id FROM dw_form_table_bindings
      WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id)
    );

  DELETE FROM rt_lookup_configs
    WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id);
  DELETE FROM rt_view_fields
    WHERE view_config_id IN (
      SELECT id FROM rt_view_configs
      WHERE binding_id IN (
        SELECT id FROM dw_form_table_bindings
        WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id)
      )
    );
  DELETE FROM rt_view_configs
    WHERE binding_id IN (
      SELECT id FROM dw_form_table_bindings
      WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id)
    );

  -- rt_lookup_configs references rt_view_configs(id); delete lookups first.
  DELETE FROM rt_lookup_configs
    WHERE table_id IN (
      SELECT DISTINCT relation_table_id
      FROM dw_form_table_bindings
      WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id)
        AND relation_table_id IS NOT NULL
        AND relation_table_id > 0
    );
  DELETE FROM rt_view_fields
    WHERE view_config_id IN (
      SELECT id FROM rt_view_configs
      WHERE table_id IN (
        SELECT DISTINCT relation_table_id
        FROM dw_form_table_bindings
        WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id)
          AND relation_table_id IS NOT NULL
          AND relation_table_id > 0
      )
    );
  DELETE FROM rt_view_configs
    WHERE table_id IN (
      SELECT DISTINCT relation_table_id
      FROM dw_form_table_bindings
      WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id)
        AND relation_table_id IS NOT NULL
        AND relation_table_id > 0
    );
  -- NOTE: relation table 'test' (id=1) is EXTERNAL/shared (referenced by rt_table_access
  -- and other FUs). Its definition/fields/versions/data are NOT deleted here; the seeds
  -- below upsert them via ON CONFLICT so re-runs stay idempotent without destroying shared data.

  DELETE FROM dw_form_table_bindings WHERE form_id IN (SELECT id FROM dw_form_definitions WHERE function_unit_id = v_fu_id);
  DELETE FROM dw_form_definitions WHERE function_unit_id = v_fu_id;
  DELETE FROM dw_process_definitions WHERE function_unit_id = v_fu_id;
  DELETE FROM dw_action_definitions WHERE function_unit_id = v_fu_id;
  DELETE FROM dw_table_relations WHERE function_unit_id = v_fu_id;
  DELETE FROM dw_field_definitions WHERE table_id IN (SELECT id FROM dw_table_definitions WHERE function_unit_id = v_fu_id);
  DELETE FROM dw_table_definitions WHERE function_unit_id = v_fu_id;
  DELETE FROM dw_function_units WHERE id = v_fu_id;
END $cleanup$;



-- Relation Table (rt_*) structure linked to this function unit (external table 'test').
-- Data rows excluded; lookup/view configs now embedded in form config_json.relationViews.
-- ---------------------------------------------------------------------------

COMMIT;

